func (t *LinterOutput) decodeCBOR(dec *cborDec) error {
	n, err := dec.readMapHeader()
	if err != nil {
		return err
	}
	for i := 0; i < n; i++ {
		key, err := dec.readTextString()
		if err != nil {
			return err
		}
		switch key {
		case "findings":
			{
				sn, err := dec.readArrayHeader()
				if err != nil {
					return err
				}
				s := make([]Diagnostic, 0, sn)
				for si := 0; si < sn; si++ {
					var ev Diagnostic
					if err := (&ev).decodeCBOR(dec); err != nil {
						return err
					}
					s = append(s, ev)
				}
				t.Findings = s
			}
		case "error":
			if s, err := dec.readTextString(); err != nil {
				return err
			} else {
				t.Error = s
			}
		default:
			if err := dec.skip(); err != nil {
				return err
			}
		}
	}
	return nil
}

// DecodeCBORStrict decodes LinterOutput exactly as DecodeCBOR does, except
